package com.nstut.biotech.jei;

import com.nstut.biotech.Biotech;import com.nstut.biotech.machines.MachineRegistries;import com.nstut.biotech.recipes.GreenhouseRecipe;import com.nstut.nstutlib.recipes.OutputItem;import mezz.jei.api.constants.VanillaTypes;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.recipe.IFocusGroup;import mezz.jei.api.recipe.RecipeIngredientRole;import mezz.jei.api.recipe.RecipeType;import mezz.jei.api.recipe.category.IRecipeCategory;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.network.chat.Component;import net.minecraft.resources.Identifier;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.Ingredient;import net.neoforged.neoforge.fluids.FluidStack;import org.jetbrains.annotations.NotNull;import java.util.List;
public class GreenhouseCategory implements IRecipeCategory<GreenhouseRecipe>{public static final Identifier UID=Identifier.fromNamespaceAndPath(Biotech.MOD_ID,MachineRegistries.GREENHOUSE.id());public static final Identifier TEXTURE=Identifier.fromNamespaceAndPath(Biotech.MOD_ID,"textures/gui/jei/"+MachineRegistries.GREENHOUSE.id()+".png");public static final RecipeType<GreenhouseRecipe> TYPE=new RecipeType<>(UID,GreenhouseRecipe.class);private final IDrawable background,icon;public GreenhouseCategory(IGuiHelper h){background=h.createDrawable(TEXTURE,0,0,153,52);icon=h.createDrawableIngredient(VanillaTypes.ITEM_STACK,new ItemStack(MachineRegistries.GREENHOUSE.blockItem().get()));}@Override public @NotNull RecipeType<GreenhouseRecipe> getRecipeType(){return TYPE;}@Override public @NotNull Component getTitle(){return Component.translatable("block.biotech."+MachineRegistries.GREENHOUSE.id());}@Override public int getWidth(){return background.getWidth();}@Override public int getHeight(){return background.getHeight();}@Override public @NotNull IDrawable getIcon(){return icon;}@Override public void setRecipe(@NotNull IRecipeLayoutBuilder b,@NotNull GreenhouseRecipe r,@NotNull IFocusGroup f){List<Ingredient> i=r.getItemIngredients().stream().map(v->Ingredient.of(v.getItemStack())).toList();FluidStack fl=r.getFluidIngredients().get(0);List<Ingredient> o=r.getItemOutputs().stream().map(v->Ingredient.of(v.getItemStack())).toList();b.addSlot(RecipeIngredientRole.INPUT,23,1).addIngredients(i.get(0));if(i.size()>1)b.addSlot(RecipeIngredientRole.INPUT,41,1).addIngredients(i.get(1));b.addSlot(RecipeIngredientRole.INPUT,32,21).addFluidStack(fl.getFluid(),fl.getAmount()).setFluidRenderer(fl.getAmount(),false,16,16);for(int n=0;n<o.size();n++)b.addSlot(RecipeIngredientRole.OUTPUT,96+n*20,6).addIngredients(o.get(n));}@Override public void draw(GreenhouseRecipe r,@NotNull IRecipeSlotsView s,@NotNull GuiGraphicsExtractor g,double x,double y){background.draw(g);g.text(Minecraft.getInstance().font,"Energy: "+r.getTotalEnergy()+" FE",0,42,4210752,false);List<OutputItem> o=r.getItemOutputs();for(int n=0;n<o.size();n++){String chance=o.get(n).getChance()<1?(int)(o.get(n).getChance()*100)+"%":"";g.text(Minecraft.getInstance().font,chance,96+n*20,25,4210752,false);}}}
